from __future__ import annotations

import os
import re
from datetime import datetime
from enum import StrEnum
from pathlib import Path

from pydantic import BaseModel, ConfigDict, Field, field_validator


_SHA256_RE = re.compile(r"^[0-9a-f]{64}$")


class DocumentIntakeStatus(StrEnum):
    RECEIVED = "received"


class IntakeStorageDescriptor(BaseModel):
    model_config = ConfigDict(extra="forbid", frozen=True)

    profile: str = Field(min_length=1, max_length=64)
    bucket: str = Field(min_length=1, max_length=255)
    object_key: str = Field(min_length=1, max_length=1024)


class DocumentIntakeRequest(BaseModel):
    model_config = ConfigDict(extra="forbid")

    filename: str = Field(min_length=1, max_length=255)
    content_type: str = Field(min_length=1, max_length=255)
    size_bytes: int = Field(gt=0, le=10_000_000_000)
    checksum_sha256: str = Field(min_length=64, max_length=64)
    source_ref: str | None = Field(default=None, max_length=512)
    metadata: dict[str, str] = Field(default_factory=dict)

    @field_validator("filename")
    @classmethod
    def validate_filename(cls, value: str) -> str:
        candidate = value.strip()
        if not candidate:
            raise ValueError("filename must not be blank")
        if "\\" in candidate or "/" in candidate:
            raise ValueError("filename must not contain path separators")
        if candidate in {".", ".."}:
            raise ValueError("filename must be a concrete file name")
        if os.path.basename(candidate) != candidate:
            raise ValueError("filename must not include parent directories")
        if not Path(candidate).suffix:
            raise ValueError("filename must include a supported extension")
        return candidate

    @field_validator("content_type")
    @classmethod
    def normalize_content_type(cls, value: str) -> str:
        candidate = value.strip().lower()
        if not candidate:
            raise ValueError("content_type must not be blank")
        return candidate

    @field_validator("checksum_sha256")
    @classmethod
    def validate_checksum(cls, value: str) -> str:
        candidate = value.strip().lower()
        if not _SHA256_RE.fullmatch(candidate):
            raise ValueError("checksum_sha256 must be a 64 character lowercase hexadecimal SHA-256 digest")
        return candidate

    @field_validator("source_ref")
    @classmethod
    def normalize_source_ref(cls, value: str | None) -> str | None:
        if value is None:
            return None
        candidate = value.strip()
        return candidate or None

    @field_validator("metadata")
    @classmethod
    def validate_metadata(cls, value: dict[str, str]) -> dict[str, str]:
        normalized: dict[str, str] = {}
        for raw_key, raw_value in value.items():
            key = raw_key.strip()
            item_value = raw_value.strip()
            if not key:
                raise ValueError("metadata keys must not be blank")
            if not item_value:
                raise ValueError(f"metadata value for '{key}' must not be blank")
            normalized[key] = item_value
        return normalized

    @property
    def filename_extension(self) -> str:
        return Path(self.filename).suffix.lower()


class DocumentIntakeRecord(BaseModel):
    model_config = ConfigDict(extra="forbid", frozen=True)

    intake_id: str = Field(min_length=1, max_length=128)
    status: DocumentIntakeStatus
    received_at: datetime
    filename: str = Field(min_length=1, max_length=255)
    content_type: str = Field(min_length=1, max_length=255)
    size_bytes: int = Field(gt=0)
    checksum_sha256: str = Field(min_length=64, max_length=64)
    source_ref: str | None = Field(default=None, max_length=512)
    metadata: dict[str, str] = Field(default_factory=dict)
    storage: IntakeStorageDescriptor
    duplicate_of: str | None = Field(default=None, max_length=128)


class DocumentIntakeResponse(BaseModel):
    model_config = ConfigDict(extra="forbid", frozen=True)

    accepted: bool = True
    created: bool
    document: DocumentIntakeRecord
