from __future__ import annotations

import json
import re
from datetime import datetime, timezone
from pathlib import Path
from typing import Protocol

from .contracts import DocumentIntakeRecord, IntakeStorageDescriptor


_SAFE_FILENAME_RE = re.compile(r"[^a-zA-Z0-9._-]+")


class StorageError(RuntimeError):
    """Raised when the intake record store cannot persist or retrieve data."""


class IntakeRecordStore(Protocol):
    def allocate_storage_descriptor(
        self,
        *,
        intake_id: str,
        filename: str,
        received_at: datetime,
    ) -> IntakeStorageDescriptor: ...

    def find_by_checksum(self, checksum_sha256: str) -> DocumentIntakeRecord | None: ...

    def save(self, record: DocumentIntakeRecord) -> DocumentIntakeRecord: ...


class FileSystemIntakeRecordStore:
    """
    Local-dev compatible intake record store.

    The business contract remains object-storage oriented through the returned
    storage descriptor, while persistence is expressed as reviewable filesystem
    manifests for this REQ slice.
    """

    def __init__(self, root: Path, *, storage_profile: str, bucket: str) -> None:
        self.root = Path(root)
        self.storage_profile = storage_profile
        self.bucket = bucket
        self.manifest_dir = self.root / "manifests"
        self.checksum_dir = self.root / "checksums"
        self.manifest_dir.mkdir(parents=True, exist_ok=True)
        self.checksum_dir.mkdir(parents=True, exist_ok=True)

    def allocate_storage_descriptor(
        self,
        *,
        intake_id: str,
        filename: str,
        received_at: datetime,
    ) -> IntakeStorageDescriptor:
        received_utc = _as_utc(received_at)
        date_partition = received_utc.strftime("%Y/%m/%d")
        safe_filename = _sanitize_filename(filename)
        object_key = f"pending/{date_partition}/{intake_id}-{safe_filename}"
        return IntakeStorageDescriptor(
            profile=self.storage_profile,
            bucket=self.bucket,
            object_key=object_key,
        )

    def get(self, intake_id: str) -> DocumentIntakeRecord | None:
        manifest_path = self.manifest_dir / f"{intake_id}.json"
        if not manifest_path.exists():
            return None
        try:
            payload = json.loads(manifest_path.read_text(encoding="utf-8"))
            return DocumentIntakeRecord.model_validate(payload)
        except (OSError, json.JSONDecodeError, ValueError) as exc:
            raise StorageError(f"failed to read intake record '{intake_id}'") from exc

    def find_by_checksum(self, checksum_sha256: str) -> DocumentIntakeRecord | None:
        checksum_path = self.checksum_dir / f"{checksum_sha256}.json"
        if not checksum_path.exists():
            return None
        try:
            payload = json.loads(checksum_path.read_text(encoding="utf-8"))
            intake_id = payload["intake_id"]
        except (OSError, json.JSONDecodeError, KeyError) as exc:
            raise StorageError(f"failed to read checksum index '{checksum_sha256}'") from exc
        return self.get(intake_id)

    def save(self, record: DocumentIntakeRecord) -> DocumentIntakeRecord:
        manifest_path = self.manifest_dir / f"{record.intake_id}.json"
        checksum_path = self.checksum_dir / f"{record.checksum_sha256}.json"

        try:
            _write_json_atomic(manifest_path, record.model_dump(mode="json"))
            if not checksum_path.exists():
                _write_json_atomic(
                    checksum_path,
                    {
                        "intake_id": record.intake_id,
                        "checksum_sha256": record.checksum_sha256,
                    },
                )
        except OSError as exc:
            raise StorageError(f"failed to persist intake record '{record.intake_id}'") from exc

        return record


def _sanitize_filename(filename: str) -> str:
    sanitized = _SAFE_FILENAME_RE.sub("-", filename.strip())
    sanitized = sanitized.strip("-.")
    return sanitized or "document.bin"


def _write_json_atomic(path: Path, payload: object) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary_path = path.with_suffix(f"{path.suffix}.tmp")
    temporary_path.write_text(
        json.dumps(payload, indent=2, sort_keys=True),
        encoding="utf-8",
    )
    temporary_path.replace(path)


def _as_utc(value: datetime) -> datetime:
    if value.tzinfo is None:
        return value.replace(tzinfo=timezone.utc)
    return value.astimezone(timezone.utc)
