from __future__ import annotations

from fastapi import APIRouter, HTTPException, Response, status

from .contracts import DocumentIntakeRequest, DocumentIntakeResponse
from .runtime import DocumentIntakeRuntimeSettings, build_document_intake_service
from .service import DocumentIntakeService, DocumentIntakeValidationError
from .storage import StorageError


def build_router(
    *,
    settings: DocumentIntakeRuntimeSettings | None = None,
    service: DocumentIntakeService | None = None,
) -> APIRouter:
    resolved_settings = settings or DocumentIntakeRuntimeSettings.from_env()
    resolved_service = service or build_document_intake_service(resolved_settings)

    router = APIRouter(
        prefix=f"{resolved_settings.api_prefix}/documents",
        tags=["document-intake"],
    )

    @router.post(
        "/intake",
        response_model=DocumentIntakeResponse,
        status_code=status.HTTP_201_CREATED,
    )
    def intake_document(
        payload: DocumentIntakeRequest,
        response: Response,
    ) -> DocumentIntakeResponse:
        try:
            result = resolved_service.submit(payload)
        except DocumentIntakeValidationError as exc:
            raise HTTPException(status_code=status.HTTP_422_UNPROCESSABLE_ENTITY, detail=str(exc)) from exc
        except StorageError as exc:
            raise HTTPException(
                status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,
                detail="document intake storage failure",
            ) from exc

        if not result.created:
            response.status_code = status.HTTP_200_OK
        return result

    return router
