from __future__ import annotations

import uuid
from collections.abc import Callable, Iterable
from datetime import datetime, timezone

from .contracts import (
    DocumentIntakeRecord,
    DocumentIntakeRequest,
    DocumentIntakeResponse,
    DocumentIntakeStatus,
)
from .storage import IntakeRecordStore


_EXTENSION_CONTENT_TYPES: dict[str, set[str]] = {
    ".pdf": {"application/pdf"},
    ".docx": {"application/vnd.openxmlformats-officedocument.wordprocessingml.document"},
    ".xlsx": {"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"},
    ".pptx": {"application/vnd.openxmlformats-officedocument.presentationml.presentation"},
    ".jpg": {"image/jpeg", "image/jpg"},
    ".jpeg": {"image/jpeg", "image/jpg"},
    ".png": {"image/png"},
}


class DocumentIntakeValidationError(ValueError):
    """Raised when a document intake request fails business validation."""


class DocumentIntakeService:
    def __init__(
        self,
        *,
        record_store: IntakeRecordStore,
        max_size_bytes: int,
        allowed_content_types: Iterable[str],
        allowed_extensions: Iterable[str],
        clock: Callable[[], datetime] | None = None,
        id_factory: Callable[[], str] | None = None,
    ) -> None:
        self.record_store = record_store
        self.max_size_bytes = max_size_bytes
        self.allowed_content_types = {item.strip().lower() for item in allowed_content_types if item.strip()}
        self.allowed_extensions = {item.strip().lower() for item in allowed_extensions if item.strip()}
        self.clock = clock or (lambda: datetime.now(timezone.utc))
        self.id_factory = id_factory or (lambda: f"din-{uuid.uuid4().hex}")

        if self.max_size_bytes <= 0:
            raise ValueError("max_size_bytes must be greater than zero")
        if not self.allowed_content_types:
            raise ValueError("allowed_content_types must not be empty")
        if not self.allowed_extensions:
            raise ValueError("allowed_extensions must not be empty")

    def submit(self, request: DocumentIntakeRequest) -> DocumentIntakeResponse:
        self._validate_request(request)

        existing_record = self.record_store.find_by_checksum(request.checksum_sha256)
        if existing_record is not None:
            return DocumentIntakeResponse(
                accepted=True,
                created=False,
                document=existing_record,
            )

        received_at = self._as_utc(self.clock())
        intake_id = self.id_factory().strip()
        if not intake_id:
            raise ValueError("id_factory must return a non-empty identifier")

        storage = self.record_store.allocate_storage_descriptor(
            intake_id=intake_id,
            filename=request.filename,
            received_at=received_at,
        )

        record = DocumentIntakeRecord(
            intake_id=intake_id,
            status=DocumentIntakeStatus.RECEIVED,
            received_at=received_at,
            filename=request.filename,
            content_type=request.content_type,
            size_bytes=request.size_bytes,
            checksum_sha256=request.checksum_sha256,
            source_ref=request.source_ref,
            metadata=request.metadata,
            storage=storage,
            duplicate_of=None,
        )
        self.record_store.save(record)

        return DocumentIntakeResponse(
            accepted=True,
            created=True,
            document=record,
        )

    def _validate_request(self, request: DocumentIntakeRequest) -> None:
        if request.size_bytes > self.max_size_bytes:
            raise DocumentIntakeValidationError(
                f"document size {request.size_bytes} exceeds configured maximum of {self.max_size_bytes} bytes"
            )

        if request.content_type not in self.allowed_content_types:
            raise DocumentIntakeValidationError(
                f"content type '{request.content_type}' is not allowed for document intake"
            )

        extension = request.filename_extension
        if extension not in self.allowed_extensions:
            raise DocumentIntakeValidationError(
                f"file extension '{extension}' is not allowed for document intake"
            )

        compatible_types = _EXTENSION_CONTENT_TYPES.get(extension)
        if compatible_types and request.content_type not in compatible_types:
            raise DocumentIntakeValidationError(
                f"content type '{request.content_type}' does not match file extension '{extension}'"
            )

    @staticmethod
    def _as_utc(value: datetime) -> datetime:
        if value.tzinfo is None:
            return value.replace(tzinfo=timezone.utc)
        return value.astimezone(timezone.utc)
