DEFAULT_STORAGE_PROFILE = "local"
DEFAULT_STORAGE_BUCKET = "document-intake"


class DocumentIntakeConfigurationError(ValueError):
    """Raised when runtime configuration is incomplete or invalid."""


@dataclass(frozen=True)
class DocumentIntakeRuntimeSettings:
    api_prefix: str = DEFAULT_API_PREFIX
    storage_profile: str = DEFAULT_STORAGE_PROFILE
    storage_root: Path = Path(".local/document-intake")
    storage_bucket: str = DEFAULT_STORAGE_BUCKET
    max_size_bytes: int = DEFAULT_MAX_SIZE_BYTES
    allowed_content_types: tuple[str, ...] = DEFAULT_ALLOWED_CONTENT_TYPES
    allowed_extensions: tuple[str, ...] = DEFAULT_ALLOWED_EXTENSIONS

    @classmethod
    def from_env(cls, env: Mapping[str, str] | None = None) -> "DocumentIntakeRuntimeSettings":
        source = env or os.environ

        api_prefix = _normalize_api_prefix(source.get("DOCUMENT_INTAKE_API_PREFIX", DEFAULT_API_PREFIX))
        storage_profile = source.get("DOCUMENT_INTAKE_STORAGE_PROFILE", DEFAULT_STORAGE_PROFILE).strip() or DEFAULT_STORAGE_PROFILE
        storage_root = Path(source.get("DOCUMENT_INTAKE_STORAGE_ROOT", ".local/document-intake"))
        storage_bucket = source.get("DOCUMENT_INTAKE_STORAGE_BUCKET", DEFAULT_STORAGE_BUCKET).strip() or DEFAULT_STORAGE_BUCKET

        try:
            max_size_bytes = int(source.get("DOCUMENT_INTAKE_MAX_SIZE_BYTES", str(DEFAULT_MAX_SIZE_BYTES)))
        except ValueError as exc:
            raise DocumentIntakeConfigurationError("DOCUMENT_INTAKE_MAX_SIZE_BYTES must be an integer") from exc
        if max_size_bytes <= 0:
            raise DocumentIntakeConfigurationError("DOCUMENT_INTAKE_MAX_SIZE_BYTES must be greater than zero")

        allowed_content_types = _parse_csv(
            source.get(
                "DOCUMENT_INTAKE_ALLOWED_CONTENT_TYPES",
                ",".join(DEFAULT_ALLOWED_CONTENT_TYPES),
            )
        )
        allowed_extensions = tuple(item.lower() for item in _parse_csv(source.get("DOCUMENT_INTAKE_ALLOWED_EXTENSIONS", ",".join(DEFAULT_ALLOWED_EXTENSIONS))))

        if not allowed_content_types:
            raise DocumentIntakeConfigurationError("DOCUMENT_INTAKE_ALLOWED_CONTENT_TYPES must not be empty")
        if not allowed_extensions:
            raise DocumentIntakeConfigurationError("DOCUMENT_INTAKE_ALLOWED_EXTENSIONS must not be empty")

        return cls(
            api_prefix=api_prefix,
            storage_profile=storage_profile,
            storage_root=storage_root,
            storage_bucket=storage_bucket,
            max_size_bytes=max_size_bytes,
            allowed_content_types=allowed_content_types,
            allowed_extensions=allowed_extensions,
        )


def build_document_intake_service(
    settings: DocumentIntakeRuntimeSettings | None = None,
) -> DocumentIntakeService:
    resolved_settings = settings or DocumentIntakeRuntimeSettings.from_env()
    record_store = FileSystemIntakeRecordStore(
        resolved_settings.storage_root,
        storage_profile=resolved_settings.storage_profile,
        bucket=resolved_settings.storage_bucket,
    )
    return DocumentIntakeService(
        record_store=record_store,
        max_size_bytes=resolved_settings.max_size_bytes,
        allowed_content_types=resolved_settings.allowed_content_types,
        allowed_extensions=resolved_settings.allowed_extensions,
    )


def _parse_csv(value: str) -> tuple[str, ...]:
    return tuple(item.strip().lower() for item in value.split(",") if item.strip())


def _normalize_api_prefix(value: str) -> str:
    candidate = value.strip() or DEFAULT_API_PREFIX
    if not candidate.startswith("/"):
        candidate = f"/{candidate}"
    return candidate.rstrip("/") or "/"
