        storage_profile="local",
        bucket="document-intake",
    )
    service = DocumentIntakeService(
        record_store=store,
        max_size_bytes=2048,
        allowed_content_types=("application/pdf", "image/png"),
        allowed_extensions=(".pdf", ".png"),
        clock=lambda: datetime(2024, 1, 2, 3, 4, 5, tzinfo=timezone.utc),
        id_factory=lambda: "din-fixed-001",
    )
    return service, store


def _make_request(**overrides: object) -> DocumentIntakeRequest:
    payload: dict[str, object] = {
        "filename": "invoice.pdf",
        "content_type": "application/pdf",
        "size_bytes": 1024,
        "checksum_sha256": "a" * 64,
        "source_ref": "mailroom-batch-001",
        "metadata": {"department": "finance"},
    }
    payload.update(overrides)
    return DocumentIntakeRequest.model_validate(payload)


def test_submit_persists_record_and_storage_descriptor(tmp_path: Path) -> None:
    service, store = _make_service(tmp_path)

    response = service.submit(_make_request())

    assert response.accepted is True
    assert response.created is True
    assert response.document.intake_id == "din-fixed-001"
    assert response.document.status == "received"
    assert response.document.storage.profile == "local"
    assert response.document.storage.bucket == "document-intake"
    assert response.document.storage.object_key == "pending/2024/01/02/din-fixed-001-invoice.pdf"

    persisted = store.get("din-fixed-001")
    assert persisted == response.document
    assert (store.manifest_dir / "din-fixed-001.json").exists()
    assert (store.checksum_dir / f'{"a" * 64}.json').exists()


def test_submit_rejects_unsupported_content_type(tmp_path: Path) -> None:
    service, _ = _make_service(tmp_path)

    with pytest.raises(DocumentIntakeValidationError, match="not allowed"):
        service.submit(
            _make_request(
                filename="scan.jpg",
                content_type="image/jpeg",
                checksum_sha256="b" * 64,
            )
        )


def test_submit_rejects_extension_content_type_mismatch(tmp_path: Path) -> None:
